def seed(apps, schema_editor):
    User = apps.get_model("rouh", "User")
    SignInEmail = apps.get_model("rouh", "SignInEmail")
    taken = set(SignInEmail.objects.values_list("email", flat=True))
    now = time.time()
    for user in User.objects.filter(is_active=True).order_by("date_joined", "pk"):
        email = (user.email or "").strip().lower()
        if not email and "@" in (user.username or ""):
            email = user.username.strip().lower()
        if not email or "@" not in email or email in taken:
            continue
        taken.add(email)
        SignInEmail.objects.create(email=email, user_id=user.pk, primary=True, added_at=now, source="account")


